import * as dgram from 'node:dgram';
import * as dns from 'node:dns';
function main(): void {
  const d: any = dgram;
  console.log(typeof d._createSocketHandle, d._createSocketHandle.length, Object.keys(d).join());
  console.log(Intl.supportedValuesOf('calendar').join());
  console.log(Intl.supportedValuesOf('collation').join());
  console.log(Intl.supportedValuesOf('numberingSystem').length, Intl.supportedValuesOf('numberingSystem').slice(0, 5).join());
  console.log(Intl.supportedValuesOf('currency').length, Intl.supportedValuesOf('currency').slice(0, 5).join());
  console.log(Intl.supportedValuesOf('timeZone').length, Intl.supportedValuesOf('timeZone').slice(0, 3).join());
  console.log(Intl.supportedValuesOf('unit').join());
  const p: any = (dns as any).promises;
  const r: any = new p.Resolver();
  console.log(Object.keys(r).join(), r.constructor.name, r._handle.constructor.name, Object.keys(r._handle).length);
  const q: any = dns;
  console.log(typeof q.resolveTlsa, q.resolveTlsa.length, typeof p.resolveTlsa, p.resolveTlsa.length, typeof r.resolveTlsa);
}
